// Maps a short project key to a sheet. The map lives here, inside n8n, so
// the browser never receives a spreadsheet ID - it only ever sends
// ?project=tickets or ?project=invoices.
//
// It is also a whitelist: without it this webhook would happily read any
// spreadsheet the connected Google account can see.

const SHEETS = {
  tickets:  { sheet_id: "PASTE_TICKET_SHEET_ID_HERE", tab: "tickets" },
  invoices: { sheet_id: "PASTE_LEDGER_SHEET_ID_HERE", tab: "ledger" },
  pricing:  { sheet_id: "PASTE_PRICING_SHEET_ID_HERE", tab: "pricing_log" },

  // Project 4 writes two sheets, so it reads as two keys. The console shows
  // "onboarding" in its table and fetches "onboarding_tasks" separately to
  // fill in each row's checklist.
  onboarding:       { sheet_id: "PASTE_ONBOARDING_SHEET_ID_HERE", tab: "customers" },
  // Task rows accumulate three to four times faster than signups, so this
  // one needs a much higher cap - at 50 the checklist would silently vanish
  // from older signups.
  onboarding_tasks: { sheet_id: "PASTE_ONBOARDING_SHEET_ID_HERE", tab: "onboarding_tasks", max_rows: 400 },
};

const query = $input.first().json.query || {};
const key = String(query.project || "tickets").toLowerCase().trim();
const cfg = SHEETS[key];

if (!cfg) {
  throw new Error(
    "Unknown project '" + key + "'. Expected one of: " + Object.keys(SHEETS).join(", ")
  );
}

return [{ json: { project: key, sheet_id: cfg.sheet_id, tab: cfg.tab, max_rows: cfg.max_rows || 50 } }];

// Collapse the sheet rows into a single response item.
//
// Single item on purpose: with responseMode "responseNode", a node that
// emits zero items stops the chain and the webhook never replies - the
// caller just hangs. Always returning one item means an empty sheet gives
// an empty list instead of a timeout.

// Per-project, because the onboarding checklist sheet fills far faster than
// the others and needs a bigger window than a log of signups does.
const resolved = $("Resolve Project").first().json;
const MAX_ROWS = resolved.max_rows || 50;

const project = resolved.project;

const rows = $input
  .all()
  .map((item) => item.json)
  .filter((row) => row && Object.keys(row).length > 0 && Object.values(row).some((v) => v !== "" && v !== null));

// The sheet is append-only, so the newest row is the last one.
rows.reverse();

return [{ json: { project, count: rows.length, rows: rows.slice(0, MAX_ROWS) } }];
